Section SegsG.
Context {fx : FPState}.
Variable rom : word -> option byte.

Lemma cs_A : forall (sh : bool) regs m (s pix1 : Z) (ret : word),
  (112 <= s)%Z -> (s < 2 ^ 64)%Z -> (1 <= pix1)%Z -> (pix1 + 64 < 2 ^ 64)%Z ->
  store_ok SEGS m (Z_to_bv 64 (s - 112)) 112 = true ->
  rdn SEGS (FRC m s ret regs) (Z_to_bv 64 (pix1 + 8)) 4 = Some (Z_to_le_bytes 4 1) ->
  rdn SEGS (FRC m s ret regs) (Z_to_bv 64 0x1137e8) 4 = Some (Z_to_le_bytes 4 1) ->
  getr regs 2 = Z_to_bv 64 s -> getr regs 1 = ret -> getr regs 10 = Z_to_bv 64 pix1 -> getr regs 11 = Z_to_bv 64 pix1 ->
  getr regs 12 = Z_to_bv 64 (hsz sh) -> getr regs 13 = Z_to_bv 64 (vsz sh) ->
  exists regs',
    msteps SEGS (mkst regs (0x91ff4 : word) m rom) (mkst regs' (0x90f1c : word) (FRC m s ret regs) rom)
    /\ getr regs' 2 = Z_to_bv 64 (s - 112) /\ getr regs' 1 = Z_to_bv 64 (pcS sh)
    /\ getr regs' 8 = Z_to_bv 64 pix1 /\ getr regs' 9 = Z_to_bv 64 2 /\ getr regs' 18 = Z_to_bv 64 (hsz sh) /\ getr regs' 19 = Z_to_bv 64 (vsz sh)
    /\ getr regs' 20 = Z_to_bv 64 pix1
    /\ getr regs' 10 = Z_to_bv 64 (ssz sh) /\ getr regs' 11 = Z_to_bv 64 (sdir sh) /\ getr regs' 12 = Z_to_bv 64 (co1 sh s) /\ getr regs' 13 = Z_to_bv 64 (co2 sh s)
    /\ regs_agree (fun r => In r [1; 2; 8; 9; 10; 11; 12; 13; 18; 19; 20]%list) regs regs'.
