  getr regs 2 = Z_to_bv 64 (s - 112) -> getr regs 18 = Z_to_bv 64 pixdb -> getr regs 19 = Z_to_bv 64 pixt ->
  exists regs',
    msteps SEGS (mkst regs (Z_to_bv 64 (pcF sh)) m rom) (mkst regs' (0x8f8c8 : word) m rom)
    /\ getr regs' 1 = Z_to_bv 64 0x92364 /\ getr regs' 10 = Z_to_bv 64 pixdb /\ getr regs' 11 = Z_to_bv 64 pixt /\ getr regs' 12 = Z_to_bv 64 sel2
