(* [comment removed for export] *)
(* [comment removed for export] *)
Definition tcm (C : lctx) (A : AS) (m : word -> option byte) (p data cd : Z) (cvd : cmapv) : Prop :=
  cd = 0%Z \/
  (cd <> 0%Z /\ CMAPat m cd cvd /\ cmap_ok cvd /\
   live A (Z_to_bv 64 cd) = Some 24%Z /\ live A (Z_to_bv 64 (c_arr cvd)) = Some (4 * c_nalloc cvd)%Z /\
   live (c_A0 C) (Z_to_bv 64 cd) = None /\ live (c_A0 C) (Z_to_bv 64 (c_arr cvd)) = None /\
   cd <> c_arr cvd /\ cd <> p /\ cd <> data /\ c_arr cvd <> p /\ c_arr cvd <> data).

Definition tpx (C : lctx) (A : AS) (m : word -> option byte) (p w h cd data : Z) (cvd : cmapv) : Prop :=
  PIXat m p (hdv w h 1 cd data) /\
  live A (Z_to_bv 64 p) = Some 64%Z /\ live (c_A0 C) (Z_to_bv 64 p) = None /\
  live A (Z_to_bv 64 data) = Some (4 * (wpl_of w 1 * h))%Z /\ live (c_A0 C) (Z_to_bv 64 data) = None /\
  p <> data /\ tcm C A m p data cd cvd.

(* [comment removed for export] *)
Definition tblk (p data cd : Z) (cvd : cmapv) (q : word) : Prop :=
  q = Z_to_bv 64 p \/ q = Z_to_bv 64 data \/ (cd <> 0%Z /\ (q = Z_to_bv 64 cd \/ q = Z_to_bv 64 (c_arr cvd))).

