Lemma tpx_of_pixt : forall C A A' m' p w h cd data cv,
  pixt_new C A A' m' p w h 1 cd data cv ->
  exists cvd, tpx C A' m' p w h cd data cvd /\
    (forall q, tblk p data cd cvd q -> live A q = None) /\
    (forall q, ~ tblk p data cd cvd q -> live A' q = live A q) /\
    (cd <> 0%Z -> cmap_ok cv /\ c_d cvd = c_d cv /\ c_nalloc cvd = c_nalloc cv /\ c_n cvd = c_n cv).
