Lemma tcm_destroy : forall C A m p data cd cvd, tcm C A m p data cd cvd ->
  cd = 0%Z \/ (CMAPat m cd cvd /\ live A (Z_to_bv 64 cd) = Some 24%Z /\ live A (Z_to_bv 64 (c_arr cvd)) = Some (4 * c_nalloc cvd)%Z /\
               live (c_A0 C) (Z_to_bv 64 cd) = None /\ live (c_A0 C) (Z_to_bv 64 (c_arr cvd)) = None /\
               cd <> c_arr cvd /\ cd <> p /\ c_arr cvd <> p /\ data <> cd /\ data <> c_arr cvd /\ (0 < 4 * c_nalloc cvd)%Z).
