Definition sblk (sel : Z) (sv : selv) (q : word) : Prop := exists p, sel_blk sel sv p /\ q = Z_to_bv 64 p.

Lemma sel_keep : forall T A A' (P : word -> Prop) m m' sel sv c, (T < 2 ^ 64)%Z -> sel_at T A m sel sv -> sel_cont m sv c ->
  (forall q, sblk sel sv q -> live A' q = live A q) -> PWK A P m m' -> (forall q, sblk sel sv q -> P q) ->
  sel_at T A' m' sel sv /\ sel_cont m' sv c.
