Lemma sel_at_keepP : forall T A A' (P : word -> Prop) m m' sel sv, (T < 2 ^ 64)%Z -> sel_at T A m sel sv ->
  (forall q, sblk sel sv q -> live A' q = live A q) -> PWK A P m m' -> (forall q, sblk sel sv q -> P q) ->
