(* [comment removed for export] *)
Definition cslm (T : word -> Prop) (A A' : AS) (cm : Z) (cv : cmapv) (cm' : Z) (cv' : cmapv) : Prop :=
  (cm = 0%Z /\ cm' = 0%Z /\ forall q, ~ T q -> live A' q = live A q)
  \/ (cm <> 0%Z /\ cm' <> 0%Z /\
      c_d cv' = c_d cv /\ c_nalloc cv' = c_nalloc cv /\ c_n cv' = c_n cv /\
      (forall q, ~ T q -> q <> Z_to_bv 64 cm -> q <> Z_to_bv 64 (c_arr cv) -> q <> Z_to_bv 64 cm' -> q <> Z_to_bv 64 (c_arr cv') ->
                 live A' q = live A q) /\
      (forall q, (q = Z_to_bv 64 cm \/ q = Z_to_bv 64 (c_arr cv)) -> q <> Z_to_bv 64 cm' -> q <> Z_to_bv 64 (c_arr cv') ->
                 live A' q = None) /\
      (forall q k, live A q = Some k -> q <> Z_to_bv 64 cm -> q <> Z_to_bv 64 (c_arr cv) -> live A' q = Some k))
  \/ (cm <> 0%Z /\ cm' = 0%Z /\
      (forall q, ~ T q -> q <> Z_to_bv 64 cm -> q <> Z_to_bv 64 (c_arr cv) -> live A' q = live A q) /\
      live A' (Z_to_bv 64 cm) = None /\ live A' (Z_to_bv 64 (c_arr cv)) = None).

Lemma cslm_final : forall A A' cm cv cm' cv', cslm (fun _ => False) A A' cm cv cm' cv' -> csc_live A A' cm cv cm' cv'.
