(* [comment removed for export] *)
Definition FCL (s : Z) (ret : word) (regs : bvmap 5 word) (sh : bool) (sel1 sel2 : Z) (m : word -> option byte) : Prop :=
  FRS m s ret regs /\
  rdn SEGS m (Z_to_bv 64 (co1 sh s)) 8 = Some (Z_to_le_bytes 8 sel1) /\ rdn SEGS m (Z_to_bv 64 (co2 sh s)) 8 = Some (Z_to_le_bytes 8 sel2) /\
  rdn SEGS m (Z_to_bv 64 (cz1 sh s)) 8 = Some (Z_to_le_bytes 8 0) /\ rdn SEGS m (Z_to_bv 64 (cz2 sh s)) 8 = Some (Z_to_le_bytes 8 0).

Lemma FCL_keep : forall s ret regs sh sel1 sel2 m m', (112 <= s)%Z -> (s < 2 ^ 64)%Z -> FCL s ret regs sh sel1 sel2 m ->
